<template>
  <main v-if="seasonal" class="container python-page">
    <section class="card hero-club">
      <img class="hero-crest" :src="crest(clube)" :alt="clube.name">
      <div class="hero-copy"><h1 class="cdr-title">{{ clube.name }}</h1><p class="cdr-sub">🏟️ {{ clube.stadname }} · ⭐ Reputação {{ seasonal.starlevel }}</p>
        <div class="hero-rec"><div><div class="big">{{ seasonal.totalgames }}</div><div class="lbl">Jogos</div></div><div><div class="big w">{{ seasonal.wins }}</div><div class="lbl">Vitórias</div></div><div><div class="big d">{{ seasonal.ties }}</div><div class="lbl">Empates</div></div><div><div class="big l">{{ seasonal.losses }}</div><div class="lbl">Derrotas</div></div></div>
        <div class="bar"><div class="wbar" :style="{ width: pct('wins') + '%' }"/><div class="dbar" :style="{ width: pct('ties') + '%' }"/><div class="lbar" :style="{ width: pct('losses') + '%' }"/></div><p class="cdr-sub win-copy">Venceu {{ pct('wins').toFixed(0) }}% dos jogos</p>
      </div>
    </section>
    <section class="cdr-grid g3 metrics-grid"><MetricCard title="Ataque e defesa" :items="[['Gols marcados', seasonal.alltimegoals], ['Gols sofridos', seasonal.alltimegoalsagainst], ['Saldo', signed(seasonal.alltimegoals - seasonal.alltimegoalsagainst)], ['Gols por jogo', (seasonal.alltimegoals / seasonal.totalgames).toFixed(2)]]"/><MetricCard title="Temporadas" :items="[['Disputadas', seasonal.seasons], ['Acessos', seasonal.promotions, 'w'], ['Rebaixamentos', seasonal.relegations, 'l'], ['Melhor divisão', seasonal.bestdivision + 'ª']]"/><MetricCard title="Ranking" :items="[['Pontos no ranking', seasonal.rankingpoints], ['Melhor pontuação', seasonal.bestpoints], ['Títulos', seasonal.titleswon, 'gold'], ['Divisão atual', seasonal.currentdivision]]"/></section>
    <h2 class="cdr-section">Sala de troféus <span class="gold">{{ seasonal.titleswon }}</span></h2><section class="cdr-grid g4"><div v-for="trophy in trophies" :key="trophy.file" class="card trophy" :class="{ zero: !seasonal[trophy.key] }"><img :src="baseUrl + 'trophies/' + trophy.file + '.png'" :alt="trophy.label"><div class="big">{{ seasonal[trophy.key] }}</div><div class="lbl">{{ trophy.label }}</div></div></section>
    <h2 class="cdr-section">Últimos jogos</h2><section class="cdr-grid recent-grid"><router-link v-for="match in recent" :key="match.matchId" class="card recent-match" :to="{ name: 'partida', params: { partidaId: match.matchId } }"><img :src="crest(opponent(match))"><strong>{{ match.homeGoals }} – {{ match.awayGoals }}</strong><span class="badge" :class="match.result">{{ label(match.result) }}</span></router-link></section>
  </main>
</template>
<script>
import clubesService from '../services/clubesService'
import seasonalService from '../services/seasonalService'
import partidasService from '../services/partidasService'
import MetricCard from './MetricCard.vue'
export default { name: 'Clube', components: { MetricCard }, data: () => ({ clube: {}, seasonal: null, recent: [], clubs: {}, trophies: [{ key: 'leaguewins', label: '1ª Divisão', file: 'league_final' }, { key: 'divswon2', label: 'Divisões 2 e 3', file: '2-3_final' }, { key: 'divswon3', label: 'Divisões 4 a 7', file: '4-5-6-7_final' }, { key: 'divswon4', label: 'Divisões 8 a 10', file: '8-9-10_final' }] }), computed: { baseUrl () { return process.env.BASE_URL || '/' } }, async mounted () { const id = this.$route.params.id; this.clube = (await clubesService.get(id)).data; this.seasonal = (await seasonalService.getAll()).data; this.recent = (await partidasService.getAll(id)).data.slice(0, 10); for (const match of this.recent) { const opponent = String(match.homeClub) === String(id) ? match.awayClub : match.homeClub; this.$set(this.clubs, opponent, (await clubesService.get(opponent)).data) } }, methods: { crest (club) { const id = club && (club.iscustomteam ? club.customcrestid : club.teamId); return this.baseUrl + 'crests/' + (id || '99150901') + '.png' }, opponent (match) { const id = String(match.homeClub) === String(this.$route.params.id) ? match.awayClub : match.homeClub; return this.clubs[id] || {} }, pct (key) { return Number(this.seasonal[key] || 0) / Number(this.seasonal.totalgames || 1) * 100 }, signed (value) { return value >= 0 ? '+' + value : value }, label (result) { return { w: 'V', d: 'E', l: 'D' }[result] } } }
</script>
